(()=>{'use strict';
const D=window.AXIS_DATA,C=window.AxisCore,A=window.AxisAtlas,KEY='espana-12-ejes-v2',MEDIA='espana-12-ejes-imagenes';
const partyUI=window.AxisParties&&window.PARTY_DATA?window.AxisParties.create(window.PARTY_DATA,localStorage):null;
const ideologyUI=window.AxisIdeologies.create(window.AXIS_DATA,window.IDEOLOGY_DATA);
let partyView='intro';
function ideologyPage(){main.innerHTML=ideologyUI.render();}
function updateIdeologies(){document.querySelector('#catalog-grid').innerHTML=ideologyUI.grouped();document.querySelector('#catalog-count').textContent=ideologyUI.count();document.querySelector('.idea-chips').innerHTML=ideologyUI.chips();}
function partyPage(view='intro'){if(!partyUI)return;partyView=view;main.innerHTML=partyUI[view]();document.title='Partidos y actualidad · España en 12 ejes';}
const $=s=>document.querySelector(s),main=$('main'),dialog=$('#detail'),all=[...D.profiles,...D.ideologies,...D.contexts];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=null,images=true,filter={query:'',era:'',family:'',sector:'',documentation:'',sort:''},page=1,posterIndex=0,homeExample=0,shared=null,autoNext=false,theme='light',resultOptions={sector:'',hideConfessional:false,compareId:''};
try{theme=localStorage.getItem('espana-atlas-tema')||'light';autoNext=localStorage.getItem('espana-atlas-avance')==='on';}catch{}if(document.documentElement?.dataset)document.documentElement.dataset.theme=theme;
function activeWeights(){return shared?shared.weights:state?.weights||Array(16).fill(1);}
function asset(url){return url&&!/^(https?:|data:|blob:|\/)/.test(url)?'/'+url:url;}

try{images=localStorage.getItem(MEDIA)!=='off';const s=JSON.parse(localStorage.getItem(KEY));if(s?.version===2&&['short','full','extreme'].includes(s.mode)&&s.answers&&typeof s.answers==='object'){const qs=C.questions(D.bank,s.mode);state={version:2,mode:s.mode,answers:{},index:Math.max(0,Math.min(qs.length-1,Number.isInteger(s.index)?s.index:0)),completed:s.completed===true,weights:Array(16).fill(1)};for(const q of qs)if(Number.isInteger(s.answers[q.id])&&Math.abs(s.answers[q.id])<=2)state.answers[q.id]=s.answers[q.id];if(Array.isArray(s.weights)&&s.weights.length===16)state.weights=s.weights.map(v=>[0,1,2].includes(v)?v:1);}}catch{}
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{toast('No se puede guardar en este navegador. El test sigue funcionando.');}};
function toast(t){$('#toast').textContent=t;setTimeout(()=>{$('#toast').textContent='';},3000);}
function photo(p,large=false){const initial=p.name.split(' ').slice(0,2).map(x=>x[0]).join('');return `<div class="portrait ${large?'large':''}"><span class="initials" aria-hidden="true">${esc(initial)}</span>${images&&p.image?`<img src="${esc(asset(p.image.url))}" data-profile="${esc(p.id)}" data-fallback="${esc(p.image.fallbackUrl||p.image.remoteUrl||'')}" alt="${esc(p.name)} · ${esc(p.image.label)}" loading="lazy" decoding="async" referrerpolicy="no-referrer">`:''}</div>`;}
function flag(p,large=false){return window.AxisFlags.figure(D,p,large);}
function tag(p){return `<span class="pill">${esc(p.period)}</span>`;}
function card(p,m){const visual=p.kind==='persona'?photo(p):`<div class="card-symbol" aria-hidden="true">${p.kind==='contexto'?'⌖':'↗'}</div>`;return `<article class="card ${p.kind} ${m?'matched':''}" style="--accent:${esc(p.color)}"><div class="card-visual">${visual}<span class="card-kind">${p.kind==='persona'?'Personalidad':p.kind==='contexto'?'Lugar en su tiempo':'Corriente de ideas'}</span>${m?`<span class="card-score" aria-label="${m.similarity}% de cercanía">${m.similarity}<small>%</small></span>`:''}<div class="card-caption"><h3>${esc(p.name)}</h3><span>${esc(p.period)}</span></div></div><div class="card-body"><p class="eyebrow">${esc(p.family)}</p>${p.sector?`<span class="pill sector-tag">${esc(p.sector)}</span>`:''}${p.flag?flag(p):''}<p class="card-description">${esc(p.description)}</p>${p.kind==='persona'&&p.values.every(v=>v===null)?'<p class="catalog-only">Ficha biográfica · Sin afinidad calculada</p>':''}${m?`<div class="affinity"><div><b>${m.similarity}% de cercanía</b><span>${m.coverage} ejes comparables</span></div><div class="affinity-track"><i style="width:${m.similarity}%"></i></div>${m.conflicts.length?'<small>Tensiones en aspectos centrales</small>':''}</div>`:''}${A.strip(D,p.values)}<button class="text-button card-open" data-detail="${esc(p.id)}">${m?'Ver coincidencias y diferencias':'Explorar ficha'} <span aria-hidden="true">↗</span></button></div></article>`;}
function heading(label,title,text){return `<section class="page-heading"><p class="eyebrow">${label}</p><h1>${title}</h1><p class="lead">${text}</p></section>`;}
function home(){const examples=['campoamor','pi','jovellanos'],p=D.profiles.find(x=>x.id===examples[homeExample]),context=D.contexts.find(x=>x.id==='ctx-cartagena');main.innerHTML=`<section class="hero"><div class="hero-copy"><p class="eyebrow"><span class="live-dot" aria-hidden="true"></span> DESCUBRE TUS COORDENADAS</p><h1>¿Dónde encajan<br>tus <em>ideas políticas?</em></h1><p class="lead">Explora tu posición en 12 ejes y cuatro claves históricas. Descubre afinidades con las personas, las ideologías y los lugares de la historia de España.</p><div class="actions"><a class="button" href="#test">Descubrir mi perfil <span aria-hidden="true">→</span></a><a class="button secondary" href="#ejes">Ver los ejes</a></div><ul class="hero-benefits"><li><span aria-hidden="true">✓</span> Gratis</li><li><span aria-hidden="true">✓</span> Sin registro</li><li><span aria-hidden="true">✓</span> Cálculo local</li><li><span aria-hidden="true">✓</span> Carta descargable</li></ul></div><div class="hero-preview"><p class="preview-label">UNA VISTA DEL ATLAS · SIN DATOS PERSONALES</p><article class="preview-panel"><div class="preview-top"><div><span class="preview-tag">IDEAS CON HISTORIA</span><h2>${esc(p.family)}</h2><p>${esc(p.period)}</p></div><span class="preview-seal">12<small>EJES + 4 CLAVES</small></span></div><button class="preview-profile" data-detail="${esc(p.id)}">${photo(p)}<span><small>PERSONALIDAD DEL ATLAS</small><b>${esc(p.name)}</b><em>Explorar su ficha y sus fuentes ↗</em></span></button><button class="preview-place" data-detail="${esc(context.id)}"><span class="preview-flag">${D.flags[context.flag].svg}</span><span><small>UN LUGAR EN SU TIEMPO</small><b>${esc(context.name)}</b><em>${esc(context.period)}</em></span></button><div class="preview-coordinates"><small>COORDENADAS EDITORIALES DE LA FICHA</small>${A.strip(D,p.values)}</div><div class="preview-bottom"><span>Tu carta personalizada aparece al terminar el test.</span><a href="#test" aria-label="Empezar el test">↗</a></div></article><div class="preview-selector" aria-label="Explorar ejemplos del atlas">${examples.map((id,i)=>`<button data-example="${i}" aria-label="Mostrar ejemplo ${i+1}" aria-pressed="${i===homeExample}"><span></span></button>`).join('')}</div></div></section><section class="stats" aria-label="Contenido del atlas"><a href="#catalogo"><b>${D.profiles.length}</b><span>personalidades</span></a><a href="#ideologias"><b>${D.ideologies.length}</b><span>corrientes ideológicas</span></a><a href="#atlas"><b>${D.contexts.length}</b><span>contextos históricos</span></a><div><b>16</b><span>dimensiones de comparación</span></div></section><section class="steps-section"><div class="section-heading"><div><p class="eyebrow">TU PERFIL, PASO A PASO</p><h2>Más matices. Más perspectiva.</h2></div><p>No tienes que elegir una etiqueta antes de empezar.</p></div><div class="steps-grid"><article><span>01</span><h3>Responde a ideas concretas</h3><p>Elige 48, 80 o 240 preguntas. Puedes responder de forma neutral o dejar una pregunta sin datos.</p></article><article><span>02</span><h3>Encuentra tus conexiones</h3><p>Compara tu posición con corrientes, personalidades y proyectos históricos fechados.</p></article><article><span>03</span><h3>Guarda tu carta</h3><p>Descarga el resultado en PNG o SVG y abre las fichas para ver los matices y las fuentes.</p></article></div></section><section><div class="section-heading"><div><p class="eyebrow">PERSONAS, IDEAS Y CONTEXTOS</p><h2>La historia tiene muchas voces.</h2></div><a class="text-link" href="#catalogo">Explorar el catálogo ↗</a></div><div class="grid featured-grid">${['pi','arenal','durruti'].map(id=>card(D.profiles.find(x=>x.id===id))).join('')}</div></section><section class="home-axis-section" id="ejes"><div class="section-heading"><div><p class="eyebrow">12 EJES + 4 CLAVES HISTÓRICAS</p><h2>Una sola línea no basta.</h2></div><a class="text-link" href="#metodo">Cómo se calcula ↗</a></div><div class="axis-overview">${D.axes.map((a,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(a[0])}</h3><p>${esc(a[1])}<i aria-hidden="true">↔</i>${esc(a[2])}</p></article>`).join('')}</div></section><section class="banner"><div><p class="eyebrow">POLÍTICA ESPAÑOLA ACTUAL</p><h2>Compara propuestas de diez partidos.</h2><p>30 preguntas concretas, posiciones fechadas y cobertura visible. Una comparación aparte de las afinidades históricas.</p></div><a class="button" href="#partidos">Partidos y actualidad ↗</a></section><section class="faq-section"><div><p class="eyebrow">ANTES DE EMPEZAR</p><h2>Preguntas frecuentes.</h2><p>Una comparación para explorar tus ideas, con fuentes y límites visibles.</p></div><div>${[['¿Cuánto tarda?','El test breve tiene 48 preguntas y suele llevar unos 8–12 minutos. El completo tiene 80 preguntas y suele llevar unos 15–20 minutos. Puedes salir y retomarlo en este navegador.'],['¿Es un test científico?','Es una herramienta exploratoria con puntuaciones editoriales, sin validación psicométrica. Los porcentajes expresan cercanía en los ejes comparables, no identidad política ni una recomendación de voto.'],['¿Dónde se guardan mis respuestas?','En este navegador. El cálculo es local y no necesitas registrarte. Puedes borrar tus respuestas y desactivar las imágenes en Privacidad.'],['¿Qué representan los lugares históricos?','Un proyecto y un periodo determinados. Cartagena cantonal, el Reino de Asturias y el Toledo visigodo tienen fichas diferentes; no describen las ideas de sus habitantes actuales.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></section><section class="banner"><div><p class="eyebrow">TU CARTA ESTÁ POR DESCUBRIR</p><h2>Empieza por tus ideas.</h2><p>Sin cuentas. Con matices, historia y fuentes.</p></div><a class="button" href="#test">Hacer el test <span aria-hidden="true">→</span></a></section>`+A.homeAdditions(D);}
function currentList(){const route=location.hash.split('?')[0];return route==='#ideologias'?D.ideologies:route==='#atlas'?D.contexts:D.profiles;}
function catalog(){if(location.hash==='#ideologias'){ideologyPage();return;}const type=location.hash==='#ideologias'?'ideologia':location.hash==='#atlas'?'contexto':'persona';const list=currentList();const titles={persona:['PERSONALIDADES','Protagonistas de las ideas.','Política, empresa, economía, divulgación, ciencia, tecnología e historia de Hispania. Cada ficha delimita el periodo comparado y sus fuentes.'],ideologia:['CORRIENTES','Más allá de dos etiquetas.',`${D.ideologies.length} modelos de corrientes que han tenido presencia en España. Una misma persona puede acercarse a varias; las corrientes también cambian con el tiempo.`],contexto:['ATLAS HISTÓRICO','Un lugar. Una fecha. Un proyecto.','Comparaciones con instituciones y movimientos situados en el tiempo. No describen a todos los habitantes de una ciudad ni su situación actual.']};const t=titles[type];main.innerHTML=heading(...t)+`<section class="catalog-tools ${type==='persona'?'with-sector':''}"><label>Buscar<input id="search" type="search" placeholder="Nombre, idea o contexto…" value="${esc(filter.query)}"></label><label>Época<select id="era"><option value="">Todas las épocas</option>${D.eras.map(([id,name])=>`<option value="${id}" ${filter.era===id?'selected':''}>${esc(name)}</option>`).join('')}</select></label>${type==='persona'?`<label>Ámbito<select id="sector"><option value="">Todos los ámbitos</option>${D.sectors.map(f=>`<option ${filter.sector===f?'selected':''}>${esc(f)}</option>`).join('')}</select></label>`:''}<label>Familia<select id="family"><option value="">Todas las familias</option>${[...new Set(list.map(p=>p.family))].sort().map(f=>`<option ${filter.family===f?'selected':''}>${esc(f)}</option>`).join('')}</select></label><button class="button secondary" data-action="reset-filters">Limpiar filtros</button></section>${type==='persona'?`<div class="documentation-tools"><label>Tipo de ficha<select id="documentation"><option value="">Todas las fichas</option><option value="numeric" ${filter.documentation==='numeric'?'selected':''}>Con comparación provisional</option><option value="biography" ${filter.documentation==='biography'?'selected':''}>Biográficas · sin puntuación</option></select></label><button class="button secondary" data-action="database">Descargar base de personalidades ↓</button></div>`:''}<div class="catalog-order"><label>Ordenar<select id="sort"><option value="">Orden del catálogo</option><option value="name" ${filter.sort==='name'?'selected':''}>Nombre</option><option value="coverage" ${filter.sort==='coverage'?'selected':''}>Cobertura documentada</option></select></label><span>La tira de 16 marcas resume los valores editoriales. Las marcas grises indican falta de datos.</span></div><div class="era-chips" aria-label="Explorar por época"><button data-era="" aria-pressed="${filter.era===''}">Todas</button>${D.eras.filter(([id])=>list.some(p=>p.era===id)).map(([id,name])=>`<button data-era="${id}" aria-pressed="${filter.era===id}">${esc(name)} <small>${list.filter(p=>p.era===id).length}</small></button>`).join('')}</div><p id="catalog-count" class="subtle" role="status"></p><div id="catalog-grid" class="grid"></div><div id="pagination" class="pagination"></div>`;renderCards();}
function renderCards(){if(location.hash==='#ideologias'){ideologyUI.query(filter.query);updateIdeologies();return;}const q=filter.query.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();const list=currentList().filter(p=>(!filter.era||p.era===filter.era)&&(!filter.family||p.family===filter.family)&&(!filter.sector||p.sector===filter.sector)&&(!filter.documentation||(filter.documentation==='numeric'?p.values.some(v=>v!==null):p.values.every(v=>v===null)))&&[p.name,p.description,p.family,p.period,p.sector,...(p.reading||[]).map(x=>x.title)].join(' ').normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(q));if(filter.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'es'));if(filter.sort==='coverage')list.sort((a,b)=>b.values.filter(v=>v!==null).length-a.values.filter(v=>v!==null).length||a.name.localeCompare(b.name,'es'));const pages=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,pages);$('#catalog-count').textContent=`${list.length} fichas · Página ${page} de ${pages}`;$('#catalog-grid').innerHTML=list.slice((page-1)*12,page*12).map(p=>card(p)).join('')||'<p class="empty">No hay fichas con estos filtros.</p>';$('#pagination').innerHTML=`<button class="button secondary" data-page="${page-1}" ${page===1?'disabled':''}>← Anterior</button><span>${page} / ${pages}</span><button class="button secondary" data-page="${page+1}" ${page===pages?'disabled':''}>Siguiente →</button>`;}
function setup(){const formats=[['short','Breve',48,'8–12 minutos','Tres propuestas por dimensión.'],['full','Completo',80,'15–20 minutos','Cinco propuestas por dimensión.'],['extreme','En profundidad',240,'45–60 minutos','Quince propuestas por dimensión.']];const n=state?C.questions(D.bank,state.mode).length:0;main.innerHTML=heading('ELIGE TU RECORRIDO','Hasta dónde quieres explorar.','Tres formatos con enunciados propios sobre España. Puedes omitir, volver atrás y continuar en este navegador.')+`${state?`<div class="resume"><div><b>${state.completed?'Tienes un resultado guardado.':'Tienes un test en curso.'}</b><p>${Object.keys(state.answers).length} respuestas de ${n} preguntas.</p></div><button class="button" data-action="resume">${state.completed?'Ver mi resultado':'Continuar'} ↗</button></div>`:''}<div class="format-grid">${formats.map(([mode,title,count,duration,description],i)=>`<article class="option ${i===1?'dark':''}"><p class="eyebrow">${i===1?'PARA PROFUNDIZAR':'TU FORMATO'}</p><h2>${title}</h2><b class="big-number">${count}</b><p>${description}</p><p>${duration}</p><button class="button" data-start="${mode}">Empezar test ${title.toLowerCase()} ↗</button></article>`).join('')}</div><div class="quiz-settings"><button class="text-button" data-action="auto">Avance automático: ${autoNext?'activado':'desactivado'}</button><button class="text-button" data-action="theme">Tema: ${theme==='dark'?'oscuro':'claro'}</button></div><p class="notice">Herramienta exploratoria sin validación psicométrica. Las cuatro claves históricas se mantienen en todos los formatos.</p><a href="#preguntas">Leer el cuestionario</a> · <a href="#glosario">Consultar glosario</a>`;}

function start(mode){shared=null;state={version:2,mode,answers:{},index:0,completed:false,weights:Array(16).fill(1)};save();location.hash='#responder';question();}
function question(){if(!state)return setup();const qs=C.questions(D.bank,state.mode),q=qs[state.index],v=state.answers[q.id],a=D.axes[q.axis];main.innerHTML=`<section class="test-panel"><div class="test-top"><a href="#inicio">← Guardar y salir</a><span>${state.index+1} / ${qs.length}</span></div><div class="progress" role="progressbar" aria-label="Avance del test" aria-valuemin="0" aria-valuemax="${qs.length}" aria-valuenow="${state.index}"><span style="width:${state.index/qs.length*100}%"></span></div><p class="eyebrow">${q.axis<12?'EJE':'CLAVE HISTÓRICA'} ${q.axis+1} · ${esc(a[0])}</p><h1>${esc(q.text)}</h1><div class="answers">${[[2,'Muy de acuerdo'],[1,'De acuerdo'],[0,'Neutral'],[-1,'En desacuerdo'],[-2,'Muy en desacuerdo']].map(([n,label])=>`<button data-answer="${n}" aria-pressed="${v===n}" class="answer ${v===n?'selected':''}"><span>${label}</span><i aria-hidden="true">${v===n?'●':'○'}</i></button>`).join('')}</div><div class="question-actions"><button class="text-button" data-action="back" ${state.index===0?'disabled':''}>← Anterior</button><button class="text-button" data-action="skip">Omitir</button><button class="button" data-action="next" ${v===undefined?'disabled':''}>${state.index===qs.length-1?'Ver resultados':'Siguiente'} →</button></div><details class="question-help"><summary>Contexto del enunciado</summary><p>${esc(a[3])}</p><p>Este eje va de ${esc(a[1]).toLowerCase()} a ${esc(a[2]).toLowerCase()}. Neutral cuenta como 50; omitir deja la respuesta sin datos.</p><a href="#glosario">Consultar términos</a></details><div class="quiz-settings"><button class="text-button" data-action="auto">Avance automático: ${autoNext?'activado':'desactivado'}</button><button class="text-button" data-action="axis" data-axis="${q.axis}">Explicar eje ⓘ</button></div><p class="subtle">${esc(a[3])} Puedes cambiar las respuestas antes de terminar.</p></section>`;}
function advance(skip=false){const qs=C.questions(D.bank,state.mode);if(skip)delete state.answers[qs[state.index].id];else if(state.answers[qs[state.index].id]===undefined)return;if(state.index<qs.length-1){state.index++;save();question();}else{state.completed=true;save();location.hash='#resultado';}}
function scores(){if(shared)return shared.scores;return C.score(C.questions(D.bank,state.mode),state.answers);}
function axisRows(values,other){return `<div class="axis-list">${D.axes.map((a,i)=>`<div class="axis-row"><div class="axis-label"><b>${esc(a[0])}</b><span>${values[i]===null?'Sin datos':values[i]+' / 100'}${other&&other[i]!==null?' · Ficha '+other[i]:''}</span></div><div class="axis-track">${values[i]!==null?`<i style="left:${values[i]}%" title="Tu posición: ${values[i]}"></i>`:''}${other&&other[i]!==null?`<em style="left:${other[i]}%" title="Posición editorial: ${other[i]}"></em>`:''}</div><div class="poles"><span>${esc(a[1])}</span><span>${esc(a[2])}</span></div></div>`).join('')}</div>`;}
function rankSection(title,list,s){const ranked=C.rank(s,list,state.weights);return `<section class="result-section"><div class="section-heading"><h2>${title}</h2><span>Orden ajustado por cobertura y tensiones</span></div><div class="grid">${ranked.slice(0,3).map(m=>card(m.profile,m)).join('')||'<p class="empty">No hay tres ejes comparables con los pesos seleccionados.</p>'}</div></section>`;}
function result(){if(!state?.completed&&!shared){main.innerHTML=heading('RESULTADOS','Primero, tus coordenadas.','Completa un test para obtener comparaciones personalizadas.')+'<a class="button" href="#test">Ir al test ↗</a>';return;}const s=scores(),weights=activeWeights(),count=s.filter(v=>v!==null).length,canExport=count>=3&&C.rank(s,D.ideologies,weights).length>0;main.innerHTML=heading(shared?'RESULTADO COMPARTIDO':'TU ATLAS PERSONAL',count<3?'Aún faltan coordenadas.':'Una mirada completa a tus ideas.',`${count} ejes con datos · ${shared?'Coordenadas recibidas mediante enlace. No contienen las respuestas originales.':Object.keys(state.answers).length+' preguntas respondidas.'}`)+`<div class="actions result-actions"><a class="button secondary" href="#partidos">Comparar propuestas de partidos ↗</a><button class="button" data-action="download" ${canExport?'':'disabled'}>Descargar carta SVG ↓</button><button class="button secondary" data-action="png" ${canExport?'':'disabled'}>Descargar carta PNG ↓</button><button class="button secondary" data-action="share">Compartir enlace</button><button class="button secondary" data-action="report">Informe para PDF</button><button class="button secondary" data-action="priorities">Revisar prioridades</button><button class="button secondary" data-action="json">Guardar resultado JSON</button>${!shared?'<button class="text-button" data-action="review">Revisar respuestas</button>':''}</div><div id="share-output"></div>${count>=3?posterSection(s):''}${count<3?'<p class="notice">Necesitamos al menos tres ejes con respuestas para mostrar afinidades.</p>':`<p class="notice">Las cifras expresan cercanía entre ejes comparables. Los datos, la cobertura y el periodo seleccionado limitan cada comparación.</p>${A.resultSections(D,C,s,weights,resultOptions,card,axisRows)}`}<section class="weights-panel"><details><summary>Ajustar la importancia de las dimensiones</summary><p>Los pesos modifican la comparación. Excluir no elimina tus respuestas.</p><div class="weights">${D.axes.map((a,i)=>`<label>${esc(a[0])}<select data-weight="${i}" aria-label="Peso de ${esc(a[0])}">${[[0,'Excluir'],[1,'Normal'],[2,'Doble']].map(([n,label])=>`<option value="${n}" ${weights[i]===n?'selected':''}>${label}</option>`).join('')}</select></label>`).join('')}</div></details></section>`;}

function documentation(p){if(!p.documentation)return '';const info=p.documentation;return `<section class="documentation-panel"><p class="eyebrow">BASE DE INFORMACIÓN</p><h3>Documentación de esta personalidad</h3><dl class="documentation-facts"><div><dt>Etapa seleccionada</dt><dd>${esc(p.period)}</dd></div><div><dt>Ámbito</dt><dd>${esc(p.sector)}</dd></div><div><dt>Cobertura editorial</dt><dd>${info.numericAxes} de ${info.totalAxes} dimensiones</dd></div><div><dt>Referencias</dt><dd>${info.sourceCount} · ${esc(info.status)}</dd></div></dl><p class="notice">${esc(info.notice)}</p>${p.reading?.length?`<h4>Obras, aportaciones y rutas de lectura</h4><ul>${p.reading.map(x=>`<li>${esc(x.title)} <a href="${esc(p.sources[x.source].url)}" target="_blank" rel="noopener noreferrer">Consultar referencia ↗</a></li>`).join('')}</ul>`:''}<details class="evidence-details"><summary>Ver documentación por dimensión</summary><div class="evidence-grid">${p.evidence.map(x=>`<article><h4>${esc(D.axes[x.axis][0])}</h4><p>${esc(x.status)}</p>${x.sourceIndexes.length?`<ul>${x.sourceIndexes.map(i=>`<li><a href="${esc(p.sources[i].url)}" target="_blank" rel="noopener noreferrer">${esc(p.sources[i].title)} ↗</a></li>`).join('')}</ul>`:'<small>Sin referencia asignada a este eje.</small>'}</article>`).join('')}</div></details><details class="evidence-details"><summary>Qué falta investigar en esta ficha</summary><ul>${p.researchPriorities.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="subtle">Organización de metadatos: ${esc(info.updated)}. No certifica una revisión completa de los documentos.</p></details></section>`;}
function detail(id){const p=all.find(x=>x.id===id);if(!p)return;const s=state?.completed||shared?scores():null,m=s?C.match(s,p,activeWeights()):null;const ideology=D.ideologies.find(x=>x.id===p.ideology);let compare='';if(m){const differences=m.axes.map(i=>({i,d:Math.abs(s[i]-p.values[i])})).sort((a,b)=>a.d-b.d);compare=`<section class="comparison"><h3>Tu comparación con esta ficha</h3><p><b>${m.similarity}%</b> de cercanía en ${m.coverage} de tus ${m.available} ejes activos. ${m.coverage<8?'Analogía de cobertura limitada.':''}</p><div class="two-grid"><div><h4>Menores diferencias</h4><ul>${differences.slice(0,3).map(x=>`<li>${esc(D.axes[x.i][0])}: ${x.d} puntos de distancia</li>`).join('')}</ul></div><div><h4>Mayores diferencias</h4><ul>${differences.slice(-3).reverse().map(x=>`<li>${esc(D.axes[x.i][0])}: ${x.d} puntos de distancia</li>`).join('')}</ul></div></div>${m.conflicts.length?`<p class="notice">Tensión central en ${m.conflicts.map(i=>esc(D.axes[i][0])).join(', ')}. Coincidir en otros asuntos no implica compartir estos principios.</p>`:''}</section>`;}
$('#detail-content').innerHTML=`<div class="detail-head">${p.kind==='persona'?photo(p,true):'<span class="symbol">⌖</span>'}<div><p class="eyebrow">${esc(p.family)}</p><h2 id="detail-title">${esc(p.name)}</h2>${tag(p)}${flag(p)}<p>${esc(p.description)}</p>${ideology?`<button class="text-button" data-detail="${ideology.id}">Corriente de referencia: ${esc(ideology.name)} ↗</button>`:''}</div></div>${flag(p,true)}${window.AxisIdeologies.facts(D,p)}${documentation(p)}<p class="notice">${esc(p.limits)}</p><p>${esc(p.basis)}</p>${compare}<h3>${s?'Tus coordenadas y las de la ficha':'Posiciones editoriales de la ficha'}</h3><p class="subtle">${s?'Círculo verde: tu posición. Rombo azul: posición de la ficha.':'Círculo verde: posición de la ficha.'} Sin datos significa que no hay una comparación documentada.</p>${axisRows(s||p.values,s?p.values:null)}${A.related(D,C,p,card)}<h3>Fuentes y alcance</h3><ul class="sources">${p.sources.map(t=>`<li><a href="${esc(t.url)}" target="_blank" rel="noopener noreferrer">${esc(t.title)} ↗</a><p>${esc(t.note)}</p>${t.role?`<p class="source-role">${esc(t.role)} · ${esc(t.origin)}</p>`:''}<small>Ejes de referencia: ${t.axes.length?t.axes.map(i=>esc(D.axes[i][0])).join(', '):'Sin asignación numérica'}.</small></li>`).join('')}</ul>${p.image?`<section class="image-credit"><h3>Crédito de la imagen</h3><p>${esc(p.image.label)}. ${esc(p.image.author)}.</p><p>${esc(p.image.modifications)} ${p.image.license?'Licencia: '+esc(p.image.license)+'.':''}</p><a href="${esc(p.image.source)}" target="_blank" rel="noopener noreferrer">Archivo original y atribución ↗</a> · <a href="${esc(p.image.licenseUrl)}" target="_blank" rel="noopener noreferrer">Licencia y condiciones ↗</a></section>`:''}${p.anchors?`<h3>Figuras de referencia</h3><div class="actions">${p.anchors.map(id=>D.profiles.find(p=>p.id===id)).filter(Boolean).map(p=>`<button class="button secondary" data-detail="${p.id}">${esc(p.name)}</button>`).join('')}</div>`:''}<p><a href="/${p.kind==='persona'?'personalidades':p.kind==='ideologia'?'ideologias':'lugares'}/${esc(p.id)}/">Abrir página individual de esta ficha ↗</a></p>`;if(!dialog.open)dialog.showModal();}
function method(){main.innerHTML=heading('MÉTODO Y FUENTES','Una brújula, con sus límites.','Este proyecto es exploratorio y editorial. No es una encuesta oficial ni una medición psicométrica validada.')+`<section class="prose"><h2>Partidos y actualidad</h2><p>La comparación de partidos tiene un cuestionario propio de 30 propuestas, posiciones por afirmación y una fórmula diferente del atlas histórico. No hereda las puntuaciones de líderes ni de corrientes ideológicas. <a href="#partidos">Consulta sus fuentes, fórmulas y límites</a>.</p><h2>Qué significa “afinidad” en el atlas histórico</h2><p>Cada respuesta toma un valor de −2 a +2. Se invierte el signo cuando lo exige el enunciado, se promedian las respuestas de cada dimensión y se transforman a una escala de 0 a 100. Una respuesta neutral se convierte en 50; una omisión no aporta datos.</p><p>La cercanía es 100 menos la media ponderada de las distancias absolutas entre tus ejes y los de una ficha. Solo se compara donde ambos tienen datos; hacen falta al menos tres ejes.</p><h2>Por qué no ordenamos solo por porcentaje</h2><p>Una coincidencia en cuatro ejes medievales no tiene la misma cobertura que una comparación en catorce ejes. El orden usa: cercanía × raíz cuadrada de la proporción ponderada de ejes comparables, menos 8 puntos por desacuerdo central de al menos 55 puntos. Los ejes centrales son pluralismo, jefatura del Estado y propiedad cuando la ficha permite compararlos. El porcentaje visible sigue siendo la cercanía original.</p><h2>Catálogo y resultados distintos</h2><p>La naturaleza de una corriente (ideología, subcorriente, escuela filosófica, movimiento religioso o movimiento social) no indica su posición izquierda-derecha. Las fichas marcadas sólo catálogo no entran en la afinidad ni en las cartas. Escuelas, modelos institucionales y movimientos de una sola causa no reciben un programa completo inventado.</p><p>La ampliación V11 registra las 200 propuestas y sus decisiones. Las coordenadas retiradas de cinco fichas anteriores se conservan en la auditoría. La selección anterior de 30 mantiene una escala distinta y no participa en el ranking.</p><h2>Historia sin inventar posturas actuales</h2><p>Los ejes de inmigración, Unión Europea y medioambiente se dejan sin datos para figuras antiguas cuando su significado actual no resulta comparable. En la monarquía medieval solo se usan algunas analogías institucionales. Los lugares representan un proyecto fechado, no las preferencias de todos sus habitantes.</p><p>El Reino de Asturias de los siglos VIII–X se distingue del Reino visigodo de Toledo. Una imagen de Pelayo pintada siglos después se identifica como una representación posterior. Las dictaduras y los movimientos autoritarios se describen con sus límites y su falta de pluralismo.</p><h2>Qué dicen las fuentes</h2><p>Cada ficha enlaza los documentos o referencias utilizados. Las fuentes no publican estos números: las puntuaciones son una interpretación editorial aproximada, con incertidumbre no cuantificada. Las figuras actuales se aproximan a programas y textos seleccionados, incluidos programas de 2023; no garantizan sus posiciones en la campaña de 2026.</p><p>Los modelos de corrientes son idealizaciones: dos personas de una misma tradición pueden discrepar. Algunas figuras evolucionaron considerablemente; cada ficha indica el periodo elegido. No se deduce una doctrina completa de una única cita.</p><h2>Un catálogo abierto, no una enciclopedia completa</h2><p>La edición ${esc(D.version)} incluye ${D.profiles.length} personas, ${D.ideologies.length} corrientes y ${D.contexts.length} contextos. Es una selección: no incluye todas las personalidades ni todas las variantes ideológicas de la historia de España. Se puede ampliar editando data.js y aportando fuentes y límites para cada eje.</p><h2>Formatos, filtros y enlaces</h2><p>Los formatos contienen 48, 80 y 240 enunciados propios. El filtro confesional solo oculta ciertos modelos doctrinales, no representa una estimación de la religión de las personas. El enlace compartido contiene las coordenadas y los pesos; no contiene respuestas individuales. El mapa político utiliza únicamente Economía y Legitimidad del poder.</p><h2>Una base de información revisable</h2><p>Las fichas muestran el tipo y alcance de sus referencias, la cobertura y las tareas pendientes. Los enlaces asociados a un eje son referencias para una interpretación editorial: todavía se deben justificar los pasajes y la codificación. Las fichas biográficas no entran en el ranking.</p><p>Desde Personalidades puedes descargar el catálogo en JSON con sus fuentes, periodos y estado de documentación para proponer ampliaciones.</p><p>Revisión editorial: ${esc(D.reviewed)}.</p><div class="actions"><a class="button secondary" href="#catalogo">Consultar fichas y fuentes</a><a class="button secondary" href="#preguntas">Leer el cuestionario</a></div></section>`;}
function privacy(){main.innerHTML=heading('PRIVACIDAD','Tus respuestas se quedan aquí.','El cálculo se realiza en tu navegador. No hay cuentas, anuncios, analítica ni envío de respuestas a un servidor.')+`<section class="prose"><h2>Guardado local</h2><p>Se guarda el progreso, las respuestas y los pesos en el almacenamiento de este navegador. No se sincronizan entre dispositivos. El modo privado o el borrado de datos del navegador pueden eliminarlos.</p><h2>Preferencias y enlaces compartidos</h2><p>El tema y el avance automático se guardan en este navegador. El enlace compartido contiene coordenadas políticas y pesos: solo se comparte cuando tú copias y envías ese enlace. No incluye las respuestas individuales. Una visita a un resultado compartido no reemplaza tu test guardado.</p><h2>Imágenes externas</h2><p>El despliegue intenta descargar los retratos y servirlos desde esta web. Los que no se puedan descargar utilizan Wikimedia Commons y consultas públicas a Wikipedia para resolver la imagen y su atribución. Ese servicio recibe los datos técnicos habituales de una petición de imagen, como la dirección IP; no recibe tus respuestas. Los enlaces a fuentes te llevan a sitios externos cuando los abres. Puedes desactivar las imágenes y utilizar todo el test igualmente.</p><button class="button secondary" data-action="media">${images?'Desactivar':'Activar'} imágenes externas</button><h2>Borrar mis datos</h2><p>Este botón elimina el test guardado de las versiones 1 y 2 y las preferencias de imágenes en este navegador.</p><button class="button danger" data-action="clear">Borrar mis respuestas y preferencias</button></section>`;}
function flagsPage(){main.innerHTML=window.AxisFlags.gallery(D);}
function imagesPage(){const report=D.mediaBuildReport;main.innerHTML=heading('DIAGNÓSTICO DE IMÁGENES',`Atlas ${esc(D.version)} · Retratos`,report?`${report.downloaded} retratos descargados durante el despliegue; ${report.unresolved.length} pendientes de una ruta externa. Esta cifra no certifica la carga actual en tu navegador.`:D.bundledPortraits?`${D.bundledPortraits.count} retratos incluidos en el paquete. El informe completo de Vercel se muestra tras el build.`:'Esta vista local no tiene informe de descargas del despliegue.')+`<p class="notice">${images?'Imágenes activadas.':'Las imágenes externas están desactivadas en este navegador.'} Un aviso de imagen no disponible significa que las rutas de carga han fallado; no se sustituye un retrato real por uno inventado.</p><div class="actions"><button class="button" data-action="retry-images">Activar y volver a intentar las imágenes</button><a class="button secondary" href="#banderas">Ver todas las banderas y símbolos</a></div><div class="grid">${D.profiles.map(p=>card(p)).join('')}</div>`;}
function bank(){main.innerHTML=heading('CUESTIONARIO','Las preguntas, a la vista.','La versión breve utiliza las tres primeras de cada dimensión. La completa utiliza las cinco y el formato en profundidad utiliza las quince. El orden del test alterna las dimensiones.')+D.axes.map((a,i)=>`<details class="question-bank"><summary>${i+1}. ${esc(a[0])} <span>${i>=12?'Clave histórica':'Eje actual'}</span></summary><ol>${D.bank[i].map(([text])=>`<li>${esc(text)}</li>`).join('')}</ol></details>`).join('')+'<a class="button" href="#test">Empezar el test ↗</a>';}
function download(name,type,body){const url=URL.createObjectURL(new Blob([body],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function posterModel(){return window.AxisPoster.model({...D,ideologies:A.visible(D,D.ideologies,resultOptions)},C,scores(),activeWeights(),posterIndex);}
function posterSection(s){const m=window.AxisPoster.model({...D,ideologies:A.visible(D,D.ideologies,resultOptions)},C,s,activeWeights(),posterIndex);if(!m.idea)return '<section><p class="notice">No hay tres ejes comparables con peso para generar la carta. Activa dimensiones en los pesos para recuperar tus afinidades.</p></section>';return `<section class="poster-layout"><div><div class="deck-label"><span>TU COLECCIÓN DE AFINIDADES</span><span>${String(m.index+1).padStart(2,'0')} / ${String(m.ideos.length).padStart(2,'0')}</span></div>${window.AxisPoster.html(m,photo,flag)}<div class="deck-selector" aria-label="Seleccionar corriente de la carta">${m.ideos.map((x,i)=>`<button data-poster="${i}" aria-pressed="${i===m.index}" style="--dot:${window.AxisPoster.palettes[i]}" aria-label="Carta ${i+1}: ${esc(x.profile.name)}"><span></span>${i+1}</button>`).join('')}</div></div><aside class="poster-info"><p class="eyebrow">IDEAS CON NOMBRE PROPIO</p><h2>Una carta.<br>Muchas conexiones.</h2><p>Tu retrato de afinidades reúne una corriente ideológica, una personalidad y lugares con fecha y contexto.</p><p class="subtle">Elige una de las tres corrientes próximas para cambiar el título y el color. La personalidad y los lugares conservan sus propias comparaciones con tus respuestas.</p><div class="poster-key"><b>Cómo leer los ejes</b><p>El porcentaje de cada barra indica tu posición hacia el polo que aparece escrito. Un 50% es equilibrio; «—» significa sin respuesta.</p><b>Cómo leer las afinidades</b><p>Los porcentajes comparan solo los ejes compartidos. La cobertura y los desacuerdos centrales influyen en el orden.</p></div><a href="#metodo">Ver el método y las fuentes ↗</a></aside></section>`;}
let exporting=false,priorityStep=0;const priorities=[['¿Qué comparación quieres destacar?',0,'Organización territorial',12,'Garantías y legitimidad del poder'],['¿Qué aspecto económico pesa más para ti?',6,'Prestación de servicios',14,'Propiedad de las empresas'],['¿Qué dimensión social quieres observar más?',2,'Libertades individuales',10,'Valores y costumbres'],['¿Qué aspecto institucional quieres destacar?',9,'Religión y Estado',13,'Jefatura del Estado'],['¿Qué criterio productivo quieres comparar con mayor atención?',11,'Límites ambientales',15,'Organización del trabajo']];
function priorityPage(){if(!state?.completed&&!shared){setup();return;}const [prompt,a,labelA,b,labelB]=priorities[priorityStep];main.innerHTML=heading('REVISAR PRIORIDADES',prompt,'Estas cinco decisiones solo ajustan los pesos de comparación. No cambian tus respuestas ni tus coordenadas.')+`<section class="priority-panel"><p class="eyebrow">${priorityStep+1} / 5</p><div class="answers"><button class="answer" data-priority="${a}">Dar más peso a ${esc(labelA.toLowerCase())}</button><button class="answer" data-priority="${b}">Dar más peso a ${esc(labelB.toLowerCase())}</button><button class="answer" data-priority="equal">Compararlos con el mismo peso</button></div><button class="text-button" data-action="priority-skip">Conservar mis pesos y continuar</button></section>`;}
function priorityAdvance(){if(priorityStep<4){priorityStep++;priorityPage();}else{if(!shared)save();location.hash=shared?A.share(shared.scores,shared.weights):'#resultado';}}
function exportSvg(){if(typeof fetch==='undefined'){download('mi-carta-espana.svg','image/svg+xml',window.AxisPoster.svg(posterModel()));return;}exportCard('svg');}
async function embeddedPortrait(p){if(!images||!p?.image)return '';async function read(src){if(!src||!window.AxisMedia.safe(src)&&!src.startsWith('portraits/'))return '';const res=await fetch(asset(src),{credentials:'omit',referrerPolicy:'no-referrer',signal:AbortSignal.timeout(8000)});if(!res.ok)return '';const blob=await res.blob();if(!blob.type.startsWith('image/')||blob.size>12000000)return '';return new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(blob);});}try{const direct=await read(p.image.url);if(direct)return direct;}catch{}try{const info=await window.AxisMedia.cached(p);if(info){p.image={...p.image,...info};return await read(info.url);}}catch{}return '';}
async function exportCard(format){if(exporting)return;const m=posterModel();if(!m.idea){toast('No hay suficientes ejes comparables para generar la carta.');return;}exporting=true;toast('Preparando la carta…');try{const imagePairs=await Promise.all([m.person,...m.others].filter(Boolean).map(async x=>[x.profile.id,await embeddedPortrait(x.profile)])),imagesById=Object.fromEntries(imagePairs);imagesById.main=m.person?imagesById[m.person.profile.id]:'';const svg=window.AxisPoster.svg(m,imagesById);if(format==='svg'){download('mi-carta-espana.svg','image/svg+xml',svg);}else{const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url;});const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=img.naturalHeight||1560;canvas.getContext('2d').drawImage(img,0,0);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Sin imagen');const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='mi-carta-espana.png';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}finally{URL.revokeObjectURL(url);}}toast(imagesById.main?'Carta descargada.':images?'Carta descargada con iniciales: no se pudo incorporar el retrato.':'Carta descargada sin retratos, según tu preferencia.');}catch{toast('No se pudo crear la carta. Prueba la descarga SVG.');}finally{exporting=false;}}
function exportPng(){exportCard('png');}
function axisDetail(i){const a=D.axes[i];if(!a)return;$('#detail-content').innerHTML=`<p class="eyebrow">DIMENSIÓN ${i+1}</p><h2 id="detail-title">${esc(a[0])}</h2><p>${esc(a[3])}</p><div class="axis-definition"><article><b>0 / 100</b><h3>${esc(a[1])}</h3></article><article><b>100 / 100</b><h3>${esc(a[2])}</h3></article></div><p>Un 50 representa el centro de tus respuestas en este eje. Sin datos no equivale a una postura neutral.</p><p class="notice">La comparación histórica puede ser parcial o no resultar aplicable. Consulta las fuentes y el periodo de cada ficha.</p>`;if(!dialog.open)dialog.showModal();}
function glossary(){main.innerHTML=heading('GLOSARIO','Las palabras también importan.','Definiciones breves para leer el test. No sustituyen las diferentes interpretaciones de cada tradición.')+`<div class="glossary-grid">${D.glossary.map(([term,definition])=>`<article><h2>${esc(term)}</h2><p>${esc(definition)}</p></article>`).join('')}</div><a class="button" href="#test">Volver a elegir test</a>`;}
function reportPage(){if(!state?.completed&&!shared){setup();return;}main.innerHTML=`<div class="report-actions"><button class="button" data-action="print">Imprimir / Guardar como PDF</button><a class="button secondary" href="${shared?esc(A.share(shared.scores,shared.weights)):'#resultado'}">Volver al resultado</a></div><p class="subtle report-instructions">En la ventana de impresión, elige «Guardar como PDF». El informe incluye coordenadas, afinidades y fuentes.</p>`+A.report(D,C,scores(),activeWeights());}
function shareResult(){const fragment=A.share(scores(),activeWeights()),url=(location.origin||'')+(location.pathname||'/')+fragment;$('#share-output').innerHTML=`<section class="share-panel"><label>Enlace con tus coordenadas<input id="shared-link" type="text" readonly value="${esc(url)}"></label><button class="button secondary" data-action="copy-link">Copiar enlace</button><p class="subtle">Contiene tus 16 coordenadas y sus pesos. Quien reciba el enlace podrá verlos. No incluye respuestas individuales ni identidad.</p></section>`;}
function compareSearch(query){const folded=query.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();const found=folded?all.filter(p=>p.name.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase().includes(folded)).slice(0,8):[];$('#compare-options').innerHTML=found.map(p=>`<button data-compare="${esc(p.id)}">${esc(p.name)} <small>${esc(p.kind)}</small></button>`).join('')||(folded?'<p>No hay fichas con ese nombre.</p>':'');}
function showProfilePage(id){const p=all.find(x=>x.id===id);if(!p){main.innerHTML=heading('FICHA','No encontramos esta ficha.','Vuelve al catálogo para buscar otra personalidad, corriente o lugar.');return;}detail(id);const html=$('#detail-content').innerHTML.replace(/<h2 id="detail-title">(.*?)<\/h2>/s,'<h1 id="detail-title">$1</h1>');dialog.close();main.innerHTML=`<div class="profile-page"><a class="text-link" href="${p.kind==='persona'?'#catalogo':p.kind==='ideologia'?'#ideologias':'#atlas'}">← Volver al catálogo</a>${html}<a class="button" href="#test">${p.testEligible===false?'Explorar el test':'Comparar con mis ideas'} ↗</a></div>`;document.title=p.name+' · España en 12 ejes';}
function route(){if(location.hash==='#main'){main.focus();return;}const h=location.hash||'#inicio',catalogs=['#catalogo','#ideologias','#atlas'];main.dataset.route=h.slice(1);if(h.startsWith('#compartido?')){const decoded=A.parseShared(h);if(decoded){shared=decoded;result();}else main.innerHTML=heading('ENLACE','Este resultado no es válido.','El enlace debe contener dieciséis coordenadas y sus pesos.');}else if(h.startsWith('#idea12/')){const id=h.slice(8),content=ideologyUI.detail(id);main.innerHTML=content||heading('FICHA','No encontramos esta ideología.','Vuelve al catálogo para buscar otra corriente.');if(content)document.title=ideologyUI.selection.find(p=>p.id===id).name+' · España en 12 ejes';}else if(h.startsWith('#ficha/'))showProfilePage(h.slice(7));else if(h==='#partidos')partyPage('intro');else if(h==='#actualidad')partyPage('quiz');else if(h==='#comparacion')partyPage('results');else if(h==='#prioridades')priorityPage();else if(h==='#informe')reportPage();else if(h==='#glosario')glossary();else if(catalogs.includes(h)){filter={query:'',era:'',family:'',sector:'',documentation:'',sort:''};page=1;catalog();}else if(h==='#test')setup();else if(h==='#responder')question();else if(h==='#resultado'){shared=null;result();}else if(h==='#metodo')method();else if(h==='#privacidad')privacy();else if(h==='#preguntas')bank();else if(h==='#banderas')flagsPage();else if(h==='#imagenes')imagesPage();else home();document.querySelectorAll?.('#site-nav a').forEach(a=>{if(a.getAttribute('href')===h)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const menu=$('#menu-toggle');menu.setAttribute?.('aria-expanded','false');$('#site-nav').classList.remove?.('is-open');const titles={'#partidos':'Partidos y actualidad','#actualidad':'Cuestionario de actualidad','#comparacion':'Comparación de partidos','#catalogo':'Personalidades','#ideologias':'Ideologías','#atlas':'Atlas histórico','#test':'Elige tu test','#responder':'Cuestionario','#resultado':'Tu resultado','#metodo':'Método y fuentes','#privacidad':'Privacidad','#preguntas':'Preguntas','#banderas':'Banderas','#imagenes':'Diagnóstico de imágenes'};if(!h.startsWith('#ficha/')&&!h.startsWith('#idea12/'))document.title=(titles[h]||'Descubre tus coordenadas')+' · España en 12 ejes';if(h==='#ejes')$('#ejes').scrollIntoView?.({block:'start'});else window.scrollTo(0,0);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(partyUI&&(d.partyAction||d.partyAnswer!==undefined||d.partySelect||d.partyMode)){const view=partyUI.action(d);if(view==='export')download('coincidencias-partidos-v8.json','application/json',JSON.stringify(partyUI.report(),null,2));else{if(view==='quiz')location.hash='#actualidad';if(view==='results')location.hash='#comparacion';partyPage(view);}return;}if(d.priority!==undefined){const q=priorities[priorityStep],weights=activeWeights();if(d.priority==='equal'){weights[q[1]]=1;weights[q[3]]=1;}else{const axis=Number(d.priority);if(axis!==q[1]&&axis!==q[3])return;weights[axis]=2;weights[axis===q[1]?q[3]:q[1]]=1;}if(!shared)save();priorityAdvance();return;}if(d.ideaMode){ideologyUI.setMode(d.ideaMode);filter.query='';ideologyPage();return;}if(d.ideaGroup!==undefined){ideologyUI.setGroup(d.ideaGroup);updateIdeologies();document.querySelector('.idea-chip[data-idea-group="'+d.ideaGroup+'"]')?.focus();return;}if(d.ideaAction==='clear'){ideologyUI.clear();filter.query='';ideologyPage();return;}if(d.era!==undefined){filter.era=d.era;page=1;catalog();return;}if(d.axis!==undefined){axisDetail(Number(d.axis));return;}if(d.section){$('#resultado-'+d.section).scrollIntoView?.({behavior:'smooth',block:'start'});return;}if(d.compare){resultOptions.compareId=d.compare;$('#comparison-output').innerHTML=A.compare(D,C,scores(),activeWeights(),d.compare);$('#compare-profile').value=d.compare;return;}if(d.example!==undefined){homeExample=Math.max(0,Math.min(2,Number(d.example)||0));home();return;}if(d.action==='menu'){const toggle=$('#menu-toggle'),expanded=toggle.getAttribute('aria-expanded')==='true';toggle.setAttribute('aria-expanded',String(!expanded));$('#site-nav').classList.toggle('is-open',!expanded);return;}if(d.poster!==undefined){posterIndex=Number(d.poster);result();return;}if(d.detail)return detail(d.detail);if(d.start)return start(d.start);if(d.answer!==undefined&&state){state.answers[C.questions(D.bank,state.mode)[state.index].id]=Number(d.answer);save();question();if(autoNext){const questionId=C.questions(D.bank,state.mode)[state.index].id;setTimeout(()=>{if(autoNext&&location.hash==='#responder'&&state&&C.questions(D.bank,state.mode)[state.index].id===questionId)advance();},450);}return;}if(d.page){page=Number(d.page);renderCards();return;}switch(d.action){case'priorities':priorityStep=0;location.hash='#prioridades';break;case'priority-skip':priorityAdvance();break;case'theme':theme=theme==='light'?'dark':'light';if(document.documentElement?.dataset)document.documentElement.dataset.theme=theme;try{localStorage.setItem('espana-atlas-tema',theme);}catch{}if(shared)result();else route();break;case'auto':autoNext=!autoNext;try{localStorage.setItem('espana-atlas-avance',autoNext?'on':'off');}catch{}if(shared)result();else route();break;case'share':shareResult();break;case'copy-link':{const input=$('#shared-link');if(window.navigator?.clipboard){window.navigator.clipboard.writeText(input.value).then(()=>toast('Enlace copiado.')).catch(()=>{input.select?.();toast('Selecciona y copia el enlace.');});}else{input.select?.();toast('Selecciona y copia el enlace.');}break;}case'report':location.hash='#informe';break;case'print':window.print?.();break;case'next':advance();break;case'skip':advance(true);break;case'back':if(state.index>0){state.index--;save();question();}break;case'resume':if(state.completed)location.hash='#resultado';else{location.hash='#responder';question();}break;case'review':state.completed=false;state.index=0;save();location.hash='#responder';question();break;case'clear':partyUI?.clear();try{[KEY,MEDIA,'espana-12-ejes-v1','espana-atlas-tema','espana-atlas-avance'].forEach(k=>localStorage.removeItem(k));}catch{}state=null;shared=null;images=true;autoNext=false;theme='light';if(document.documentElement?.dataset)document.documentElement.dataset.theme=theme;privacy();toast('Datos borrados de este navegador.');break;case'media':images=!images;try{localStorage.setItem(MEDIA,images?'on':'off');}catch{}privacy();break;case'retry-images':images=true;try{localStorage.setItem(MEDIA,'on');}catch{}window.AxisMedia?.reset();imagesPage();break;case'reset-filters':filter={query:'',era:'',family:'',sector:'',documentation:'',sort:''};page=1;catalog();break;case'download':exportSvg();break;case'png':exportPng();break;case'database':download('personalidades-espana-v10.json','application/json',JSON.stringify({version:D.version,updated:D.reviewed,notice:'Catálogo seleccionado. Posiciones editoriales provisionales; no dataset científico validado.',axes:D.axes,personalities:D.profiles.map(p=>{const {mediaState,...profile}=p;return profile;})},null,2));break;case'json':download('mis-coordenadas-v2.json','application/json',JSON.stringify({version:D.version,mode:shared?'shared':state.mode,scores:scores(),weights:activeWeights(),answers:shared?{}:state.answers,notice:'Resultados exploratorios y editoriales; no diagnóstico.'},null,2));break;}});
document.addEventListener('input',e=>{if(e.target.id==='compare-search'){compareSearch(e.target.value);return;}if(e.target.id==='search'){filter.query=e.target.value;page=1;renderCards();}});
document.addEventListener('change',e=>{if(e.target.id==='idea-type'){ideologyUI.setType(e.target.value);updateIdeologies();return;}if(e.target.id==='idea-eligibility'){ideologyUI.setEligibility(e.target.value);updateIdeologies();return;}const t=e.target;if(t.id==='result-sector'){resultOptions.sector=t.value;result();return;}if(t.id==='hide-confessional'){resultOptions.hideConfessional=t.checked;result();return;}if(t.id==='compare-profile'){resultOptions.compareId=t.value;$('#comparison-output').innerHTML=A.compare(D,C,scores(),activeWeights(),t.value);return;}if(t.id==='era'||t.id==='family'||t.id==='sector'||t.id==='documentation'||t.id==='sort'){filter[t.id]=t.value;page=1;renderCards();}if(t.dataset.weight!==undefined&&(state||shared)){const i=Number(t.dataset.weight);if(i>=0&&i<16&&[0,1,2].includes(Number(t.value))){activeWeights()[i]=Number(t.value);if(!shared)save();const y=window.scrollY;result();window.scrollTo(0,y);}}});
document.addEventListener('error',e=>{if(e.target.tagName!=='IMG')return;const img=e.target,p=D.profiles.find(p=>p.id===img.dataset.profile);if(img.dataset.fallback&&!img.dataset.retried){img.dataset.retried='true';img.src=img.dataset.fallback;return;}const fail=()=>{img.hidden=true;img.parentElement.classList.add('unavailable');if(p)p.mediaState='unavailable';};if(p&&!img.dataset.resolved&&window.AxisMedia){img.dataset.resolved='true';window.AxisMedia.cached(p).then(info=>{if(!images)return;if(!info)return fail();p.image=info;p.mediaState='resolved';img.dataset.fallback=info.fallbackUrl;delete img.dataset.retried;img.src=info.url;}).catch(fail);}else fail();},true);
document.addEventListener('load',e=>{if(e.target.tagName==='IMG'){const p=D.profiles.find(p=>p.id===e.target.dataset.profile);if(p)p.mediaState='loaded';}},true);

$('#skip-link').addEventListener('click',e=>{e.preventDefault();main.focus();});
$('#close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});window.addEventListener('hashchange',route);const initialPage=document.body.dataset?.page;if(initialPage&&!location.hash)location.hash=initialPage;route();
})();

document.addEventListener('keydown',e=>{if(e.key==='/'&&location.hash==='#ideologias'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName||'')&&!document.activeElement?.isContentEditable){e.preventDefault();document.querySelector('#search')?.focus();}});
